  previous_attributes: Record<string, unknown> | null;
  /** What happened, such as customer.created. */
  type: "checkout.session.completed" | "checkout.session.expired" | "customer.created" | "customer.updated" | "customer.deleted" | "subscription.created" | "subscription.updated" | "subscription.canceled" | "subscription.past_due" | "subscription.paused" | "subscription.resumed" | "subscription.reactivated" | "subscription.plan_changed" | "subscription.trial_started" | "subscription.trial_will_end" | "subscription.trial_ended" | "subscription.payment_method_updated" | "subscription.coupon_applied" | "subscription.coupon_expired" | "payment.succeeded" | "payment.failed" | "one_shot_payment.succeeded" | "one_shot_payment.failed" | "one_shot_payment.refunded" | "refund.created" | "refund.succeeded" | "refund.failed" | "dispute.created" | "dispute.closed" | "invoice.created" | "invoice.upcoming" | "invoice.paid" | "invoice.payment_failed" | "invoice.voided" | "invoice.marked_uncollectible" | "credit_note.created" | "product.created" | "product.updated" | "product.archived" | "price.created" | "price.updated" | "price.archived" | "coupon.created" | "coupon.updated" | "webhook_endpoint.created" | "webhook_endpoint.updated" | "webhook_endpoint.deleted" | "dunning.email_required" | (string & {});
