export interface PurgedResource<TObject extends string = string> {
  /** Always true. */
  deleted: true;
  /** Id of the purged object. */
  id: string;
  /** Type of the purged object, such as customer. */
  /** The kind of object removed, such as `"customer"`. */
  object: TObject;
  /** Always true: the object's personal data was erased as well. */
  purged: true;
}

