/**
 * A webhook delivery body of a type this SDK version knows, discriminated
 * on `type`: once narrowed, `event.type === "invoice.paid"` types
 * `event.data` as an `Invoice`.
 *
 * `verifyWebhookSignature` returns `WebhookEvent | UnknownWebhookEvent`,
 * because a newer API can deliver a type this union does not name. Narrow
 * with `isKnownEventType(event)` first. New types arrive in minor releases,
 * so an exhaustive `never` check over `type` is not supported.
 */
export type WebhookEvent = WebhookEventMap[keyof WebhookEventMap];

/**
 * A webhook delivery whose `type` this SDK version does not know, usually
 * because the API is newer. Acknowledge it with a 2xx and move on: a
 * non-2xx only makes BillKit retry a delivery you will never process.
 */
export interface UnknownWebhookEvent {
  /** When the event was recorded, Unix seconds. */
  created: number;
  /** The object the event is about. Untyped: this SDK version does not know its shape. */
  data: unknown;
  /** The `evt_` id. Deduplicate on it. */
  id: string;
  livemode: boolean;
  object: "event";
  /** On an update, the fields of `data` that changed, with their values before the change. */
  previous_attributes: Record<string, unknown> | null;
  type: string & {};
}
